export type QuestType =
    | 'build_count'      // 建造 N 个某类建筑
    | 'collect_total'    // 累计收金 N
    | 'upgrade_count'    // 升级 N 次
    | 'synergy_count';   // 触发 N 次相性

export interface QuestConfigData {
    id: string;
    name: string;
    desc: string;
    type: QuestType;
    target: number;
    /** 仅 build_count 用：限定建筑类型 */
    buildingTypeId?: string;
    reward: { coins?: number };
}

